<?php
require_once __DIR__ . '/common.php'; admin_require_login();
$messages=[];try{$messages=$pdo->query('SELECT * FROM contacts ORDER BY id DESC')->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){}
admin_render_start('Contact messages');echo '<section class="panel"><div class="panel-head"><div><h2>Website enquiries</h2><p>Messages submitted through the contact form.</p></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Message</th><th>Date</th></tr></thead><tbody>';if(!$messages)echo '<tr><td colspan="5" class="empty">No contact messages found.</td></tr>';foreach($messages as $m){$name=$m['name']??$m['full_name']??'—';$email=$m['email']??'—';$phone=$m['phone']??'—';$body=$m['message']??$m['subject']??'—';$date=$m['created_at']??'—';echo '<tr><td>'.admin_e($name).'</td><td>'.admin_e($email).'</td><td>'.admin_e($phone).'</td><td class="message-cell">'.nl2br(admin_e($body)).'</td><td>'.admin_e($date).'</td></tr>';}echo '</tbody></table></div></section>';admin_render_end();
